import{d as g,C as a,o as h,c as u,j as e,a as i,E as t,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const w=JSON.parse('{"title":"论语·雍也","description":"《论语》第 6 篇「雍也」——三十章原文与导读。居敬行简、不迁怒不贰过、一箪食一瓢饮、文质彬彬、知者乐水仁者乐山。","frontmatter":{"title":"论语·雍也","description":"《论语》第 6 篇「雍也」——三十章原文与导读。居敬行简、不迁怒不贰过、一箪食一瓢饮、文质彬彬、知者乐水仁者乐山。","category":"guide","aliases":["雍也","雍也篇","雍也第六","论语雍也","lunyu 雍也"],"source":["《论语》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/lunyu/chapter-06.md","filePath":"lizhimingde/sishu-wujing/lunyu/chapter-06.md","lastUpdated":1790316338000}'),d={name:"lizhimingde/sishu-wujing/lunyu/chapter-06.md"},c=g({...d,setup(y){const s=[{id:"yi",label:"一、雍也可使南面",showLabel:!0,sentences:[["子曰：“雍也可使",{text:"南面",glossary:"nanmian"},"。”"]],note:"「雍也可使南面」——冉雍可以让他南面（居君位而治一国）。言其德足以临民。"},{id:"er",label:"二、居敬而行简",showLabel:!0,sentences:[["仲弓问子桑伯子，子曰：“可也，简。”仲弓曰：“居敬而行简，以临其民，不亦可乎？居简而行简，无乃",{text:"大简",glossary:"dajian"},"乎？”子曰：“雍之言然。”"]],note:"仲弓问子桑伯子如何。孔子答：「可也，简」——可以，他简约。仲弓说：「居敬而行简，以临其民，不亦可乎」——存心敬慎而行事简约，以此临民，不也可以吗？「居简而行简，无乃大简乎」——若存心简慢又行事简约，岂不是太简了？孔子说：「雍之言然」——你的话对。"},{id:"san",label:"三、不迁怒，不贰过",showLabel:!0,sentences:[["哀公问：“弟子孰为好学？”孔子对曰：“有颜回者好学，不",{text:"迁怒",glossary:"qiannu"},"，不",{text:"贰过",glossary:"erguo"},"。不幸短命死矣，今也则亡，未闻好学者也。”"]],note:"哀公问：弟子中谁好学？孔子答：「有颜回者好学，不迁怒，不贰过」——颜回好学：不把怒气转移到别人身上（不迁怒），不重犯同样的过错（不贰过）。「不幸短命死矣，今也则亡，未闻好学者也」——可惜短命死了，如今没有，再没听说有好学的。以「不迁怒、不贰过」定义好学，极见孔子所重。"},{id:"si",label:"四、君子周急不继富",showLabel:!0,sentences:[["子华使于齐，冉子为其母请粟，子曰：“与之",{text:"釜",glossary:"fu-liang"},"。”请益，曰：“与之",{text:"庾",glossary:"yu-liang"},"。”冉子与之粟",{text:"五秉",glossary:"wubing"},"。子曰：“赤之适齐也，乘肥马，衣轻裘。吾闻之也：君子",{text:"周急不继富",glossary:"zhoujibujifu"},"。”"]],note:"子华出使齐国，冉有为子华之母请粟。孔子说「与之釜」，请益，说「与之庾」；冉子却给了五秉（远超）。孔子说：「赤之适齐也，乘肥马，衣轻裘」——公西赤到齐国去，乘肥马、穿轻裘（本已富有）；「吾闻之也：君子周急不继富」——君子周济急难，不接济富有。"},{id:"wu",label:"五、以与尔邻里乡党",showLabel:!0,sentences:[["原思为之宰，与之粟九百，辞。子曰：“毋，以与尔邻里乡党乎！”"]],note:"原思做孔子家的总管，孔子给他粟九百，原思推辞。孔子说：「毋，以与尔邻里乡党乎」——不必推辞，把它分给你的邻里乡党吧。（与上章相对：当受则受，可施则施。）"},{id:"liu",label:"六、犁牛之子骍且角",showLabel:!0,sentences:[["子谓仲弓曰：“犁牛之子",{text:"骍且角",glossary:"xingqiejiao"},"，虽欲勿用，山川其舍诸？”"]],note:"孔子论仲弓：「犁牛之子骍且角」——耕牛之子毛色赤（骍）而角周正，「虽欲勿用，山川其舍诸」——纵想不用它祭祀，山川之神难道会舍弃它吗？喻父虽贱，子贤则当用。"},{id:"qi",label:"七、其心三月不违仁",showLabel:!0,sentences:[["子曰：“回也，其心三月不违仁，其余则日月至焉而已矣。”"]],note:"「回也，其心三月不违仁」——颜回之心，三个月不离开仁；「其余则日月至焉而已矣」——其余的人，只是偶有一日或一月达到罢了。"},{id:"ba",label:"八、由也果、赐也达、求也艺",showLabel:!0,sentences:[["季康子问：“仲由可使从政也与？”子曰：“由也果，于从政乎何有？”曰：“赐也可使从政也与？”曰：“赐也达，于从政乎何有？”曰：“求也可使从政也与？”曰：“求也艺，于从政乎何有？”"]],note:"季康子问仲由、子贡、冉求可否从政。孔子分别答：「由也果」（仲由果决），「赐也达」（子贡通达），「求也艺」（冉求多才），「于从政乎何有」——对于从政有什么困难？"},{id:"jiu",label:"九、闵子骞辞费宰",showLabel:!0,sentences:[["季氏使闵子骞为费宰，闵子骞曰：“善为我辞焉。如有复我者，则吾必在汶上矣。”"]],note:"季氏使闵子骞为费邑之宰。闵子骞说：「善为我辞焉」——好好替我推辞吧；「如有复我者，则吾必在汶上矣」——若再来找我，我一定到汶水之北去了（谓将出奔齐国）。"},{id:"shi",label:"十、斯人也而有斯疾也",showLabel:!0,sentences:[["伯牛有疾，子问之，自",{text:"牖",glossary:"you"},"执其手，曰：“亡之，命矣夫！斯人也而有斯疾也！斯人也而有斯疾也！”"]],note:"伯牛有病，孔子往问，自牖（窗）执其手，曰：「亡之，命矣夫！」——没救了，这是命啊！「斯人也而有斯疾也！斯人也而有斯疾也」——这样的人竟得这样的病！一句两叹，痛惜之情溢于言表。"},{id:"shiyi",label:"十一、贤哉回也",showLabel:!0,sentences:[["子曰：“贤哉回也！一",{text:"箪",glossary:"dan"},"食，一瓢饮，在陋巷，人不堪其忧，回也不改其乐。贤哉，回也！”"]],note:"「贤哉回也！一箪食，一瓢饮，在陋巷」——一竹篮饭、一瓢水，住在陋巷；「人不堪其忧，回也不改其乐」——别人受不了那份忧愁，颜回却不改其乐。「贤哉，回也」——首尾重叹。"},{id:"shier",label:"十二、今女画",showLabel:!0,sentences:[["冉求曰：“非不说子之道，力不足也。”子曰：“力不足者，中道而废，今女",{text:"画",glossary:"hua"},"。”"]],note:"冉求说：「非不说（悦）子之道，力不足也」——不是不喜老师之道，是力量不足。孔子说：「力不足者，中道而废」——力量不足的人，是走到半路才停下；「今女（汝）画」——如今你是自己画地自限（画＝画界而止）。"},{id:"shisan",label:"十三、君子儒与小人儒",showLabel:!0,sentences:[["子谓子夏曰：“女为君子儒，无为小人儒。”"]],note:"孔子对子夏说：「女（汝）为君子儒，无为小人儒」——你要做君子式的儒，不要做小人式的儒。"},{id:"shisi",label:"十四、行不由径",showLabel:!0,sentences:[["子游为武城宰，子曰：“女得人焉尔乎？”曰：“有澹台灭明者，行不由径，非公事，未尝至于偃之室也。”"]],note:"子游做武城之宰。孔子问：「女（汝）得人焉尔乎」——你在那里得到人才了吗？子游答：「有澹台灭明者，行不由径」——有个叫澹台灭明的，走路不走小径（径＝邪僻小路）；「非公事，未尝至于偃之室也」——不是公事，从不曾到我的房里来。"},{id:"shiwu",label:"十五、孟之反不伐",showLabel:!0,sentences:[["子曰：“孟之反不",{text:"伐",glossary:"fa-kuakou"},"，奔而殿，将入门，",{text:"策其马",glossary:"ceqima"},"曰：‘非敢后也，马不进也。’”"]],note:"「孟之反不伐」——孟之反不夸耀自己。军败退时他居后掩护（奔而殿），将入城门时却鞭打其马，说：「非敢后也，马不进也」——不是我敢殿后，是马不肯向前。写其不自伐。"},{id:"shiliu",label:"十六、不有祝鮀之佞",showLabel:!0,sentences:[["子曰：“不有祝鮀之佞，而有宋朝之美，难乎免于今之世矣。”"]],note:"「不有祝鮀之佞，而有宋朝之美，难乎免于今之世矣」——没有祝鮀那样的口才，却有宋朝那样的美貌，在当今之世就难逃祸患了。此章慨叹世风。"},{id:"shiqi",label:"十七、谁能出不由户",showLabel:!0,sentences:[["子曰：“谁能出不由户？何莫由斯道也？”"]],note:"「谁能出不由户？何莫由斯道也」——谁出门不经过门户？为何没有人走我这条道呢？以出户必由门，喻人当由道而行。"},{id:"shiba",label:"十八、文质彬彬",showLabel:!0,sentences:[["子曰：“",{text:"质胜文则野",glossary:"zhishengwen"},"，文胜质则史。",{text:"文质彬彬",glossary:"wenzhibinbin"},"，然后君子。”"]],note:"「质胜文则野，文胜质则史」——质朴胜过文饰便粗野，文饰胜过质朴便虚浮（史＝虚饰多文）。「文质彬彬，然后君子」——文与质相称，才是君子。"},{id:"shijiu",label:"十九、人之生也直",showLabel:!0,sentences:[["子曰：“人之生也直，",{text:"罔",glossary:"wang-qi"},"之生也幸而免。”"]],note:"「人之生也直，罔之生也幸而免」——人能生存，靠的是正直；不正直（罔＝诬罔、不直）而能活，只是侥幸免祸罢了。"},{id:"ershi",label:"二十、知之者不如好之者",showLabel:!0,sentences:[["子曰：“知之者不如好之者，好之者不如乐之者。”"]],note:"「知之者不如好之者，好之者不如乐之者」——知道它的人不如喜爱它的人，喜爱它的人不如以它为乐的人。三层递进，言学之深浅。"},{id:"ershiyi",label:"二十一、中人以上",showLabel:!0,sentences:[["子曰：“中人以上，可以语上也；中人以下，不可以语上也。”"]],note:"「中人以上，可以语上也；中人以下，不可以语上也」——中等以上资质的人，可以与他讲高深之理；中等以下则不可。言教当因材。"},{id:"ershier",label:"二十二、敬鬼神而远之",showLabel:!0,sentences:[["樊迟问知，子曰：“务民之义，",{text:"敬鬼神而远之",glossary:"jingguishen"},"，可谓知矣。”问仁，曰：“仁者",{text:"先难而后获",glossary:"xiannanhouhuo"},"，可谓仁矣。”"]],note:"樊迟问智。孔子说：「务民之义，敬鬼神而远之，可谓知矣」——专力于对人民合宜之事，恭敬鬼神而疏远之，可算是智了。问仁，答：「仁者先难而后获，可谓仁矣」——仁者先担艰难而后收获。"},{id:"ershisan",label:"二十三、知者乐水，仁者乐山",showLabel:!0,sentences:[["子曰：“知者乐水，仁者乐山。知者动，仁者静。知者乐，仁者寿。”"]],note:"「知者乐水，仁者乐山」——智者乐水（动而周流），仁者乐山（静而厚重）；「知者动，仁者静。知者乐，仁者寿」——智者好动，仁者好静；智者常乐，仁者长寿。"},{id:"ershisi",label:"二十四、齐一变至于鲁",showLabel:!0,sentences:[["子曰：“齐一变至于鲁，鲁一变至于道。”"]],note:"「齐一变至于鲁，鲁一变至于道」——齐国一变革可到鲁国的样子，鲁国一变革便可至于道。盖齐急功利、鲁尚礼教，故鲁近于道。"},{id:"ershiwu",label:"二十五、觚不觚",showLabel:!0,sentences:[["子曰：“",{text:"觚",glossary:"gu-jiao"},"不觚，觚哉！觚哉！”"]],note:"「觚不觚，觚哉！觚哉」——觚（酒器，上圆下方）已不像觚了，这也算觚吗！这也算觚吗！叹名实之不符。"},{id:"ershiliu",label:"二十六、君子可逝也",showLabel:!0,sentences:[["宰我问曰：“仁者，虽告之曰：‘井有仁焉。’其从之也？”子曰：“何为其然也？君子可逝也，不可陷也；可欺也，不可罔也。”"]],note:"宰我问：仁者若被告知「井里掉下一位仁人」，他会跟着跳下去吗？孔子说：「何为其然也」——何必如此？「君子可逝也，不可陷也；可欺也，不可罔也」——君子可以前去（施救），却不可被陷害；可以被欺骗（事理之所有），却不可被愚弄（事理之所无）。"},{id:"ershiqi",label:"二十七、博学于文，约之以礼",showLabel:!0,sentences:[["子曰：“君子博学于文，约之以礼，亦可以弗",{text:"畔",glossary:"pan"},"矣夫。”"]],note:"「君子博学于文，约之以礼，亦可以弗畔矣夫」——君子广泛学习文献，又以礼约束自己，也就可以不背离道了（畔＝叛、背离）。"},{id:"ershiba",label:"二十八、天厌之",showLabel:!0,sentences:[["子见南子，子路不说。夫子",{text:"矢",glossary:"shi-sworn"},"之曰：“予所否者，天厌之！天厌之！”"]],note:"孔子见南子，子路不悦。孔子发誓说：「予所否者，天厌之！天厌之」——我若有不正之处，天厌弃我！天厌弃我！"},{id:"ershijiu",label:"二十九、中庸之为德也",showLabel:!0,sentences:[["子曰：“中庸之为德也，其至矣乎！民",{text:"鲜",glossary:"xian-shao"},"久矣。”"]],note:"「中庸之为德也，其至矣乎！民鲜久矣」——中庸作为一种德，大概是至极了吧！而百姓缺少它已经很久了。（与《中庸》第三章「中庸其至矣乎，民鲜能久矣」相通。）"},{id:"sanshi",label:"三十、己欲立而立人",showLabel:!0,sentences:[["子贡曰：“如有博施于民而能济众，何如？可谓仁乎？”子曰：“何事于仁，必也圣乎！尧、舜其犹病诸！夫仁者，",{text:"己欲立而立人，己欲达而达人",glossary:"jiyulilieren"},"。能近取譬，可谓仁之方也已。”"]],note:"子贡问：若广泛施惠于民又能周济大众，如何？可算仁吗？孔子答：「何事于仁，必也圣乎」——岂止是仁，那简直是圣了！「尧、舜其犹病诸」——尧舜尚且以为难。「夫仁者，己欲立而立人，己欲达而达人」——仁者，自己要立得住也使别人立得住，自己要通达也使别人通达。「能近取譬，可谓仁之方也已」——能就近取譬（以己度人），可以说是行仁之方了。"}],r=[{id:"nanmian",term:"南面",pinyin:"nán miàn",meaning:"面向南而坐，指居君主或长官之位。可使南面：冉雍的器度可以治理一方。"},{id:"dajian",term:"大简",pinyin:"tài jiǎn",meaning:"同「太简」，过于简略。居简而行简：自己心里就苟简，再以苟简行事。"},{id:"qiannu",term:"迁怒",pinyin:"qiān nù",meaning:"把怒气转移到别人身上。不迁怒：怒于此者不迁于彼。"},{id:"erguo",term:"贰过",pinyin:"èr guò",meaning:"重复犯同一个错误。贰：重复。"},{id:"fu-liang",term:"釜",pinyin:"fǔ",meaning:"古量器名，六斗四升为一釜。"},{id:"yu-liang",term:"庾",pinyin:"yǔ",meaning:"古量器名，二斗四升为一庾（一说十六斗）。"},{id:"wubing",term:"五秉",pinyin:"wǔ bǐng",meaning:"秉：十六斛（一斛十斗）。五秉数量远超孔子所言，故下文有「周急不继富」之语。"},{id:"zhoujibujifu",term:"周急不继富",pinyin:"zhōu jí bù jì fù",meaning:"救济急难，不给富者添财。周：救济；继：增益。"},{id:"xingqiejiao",term:"骍且角",pinyin:"xīng qiě jiǎo",meaning:"骍：赤色（祭祀用牲以赤为贵）；角：牛角周正，合于祭祀之选。"},{id:"you",term:"牖",pinyin:"yǒu",meaning:"窗户。伯牛病重，孔子从窗外握其手，是避嫌，也是情深。"},{id:"dan",term:"箪",pinyin:"dān",meaning:"盛饭的圆形竹器。一箪食、一瓢饮，形容生活极简朴。"},{id:"hua",term:"画",pinyin:"huà",meaning:"画地自限、自我设限。今女画：你如今是自己给自己划了界限。"},{id:"fa-kuakou",term:"伐",pinyin:"fá",meaning:"自夸。孟之反不伐：孟之反不夸耀自己的功劳。"},{id:"ceqima",term:"策其马",pinyin:"cè qí mǎ",meaning:"鞭打自己的马。孟之反本殿后掩护，却鞭马装作是马走得慢才落在后面。"},{id:"zhishengwen",term:"质胜文则野",pinyin:"zhì shèng wén zé yě",meaning:"质朴超过文采，就显得粗野。质：内在质地；文：外在修饰。"},{id:"wenzhibinbin",term:"文质彬彬",pinyin:"wén zhì bīn bīn",meaning:"文采与质朴配合得恰到好处。彬彬：文质相杂、配合适宜的样子。"},{id:"wang-qi",term:"罔",pinyin:"wǎng",meaning:"蒙蔽、不直（此处指不正直、虚假地活着）。"},{id:"jingguishen",term:"敬鬼神而远之",pinyin:"jìng guǐ shén ér yuǎn zhī",meaning:"对鬼神存敬而不去逼近、依附。重点在「务民之义」——先尽人事。"},{id:"xiannanhouhuo",term:"先难而后获",pinyin:"xiān nán ér hòu huò",meaning:"先付出艰难，后取得收获。即先义后利、先劳后得。"},{id:"gu-jiao",term:"觚",pinyin:"gū",meaning:"古代酒器，有棱角。觚不觚：觚已不像觚了——感叹名实不符、制度走样。"},{id:"pan",term:"畔",pinyin:"pàn",meaning:"同「叛」，背离。弗畔：不会离经叛道。"},{id:"shi-sworn",term:"矢",pinyin:"shǐ",meaning:"同「誓」，发誓。"},{id:"xian-shao",term:"鲜",pinyin:"xiǎn",meaning:"少。民鲜久矣：人们缺少这种德行已经很久了。"},{id:"jiyulilieren",term:"己欲立而立人",pinyin:"jǐ yù lì ér lì rén",meaning:"自己要立得住，也让别人立得住；自己要通达，也让别人通达。这是「仁之方」——推己及人的正面表达。"}];return(b,n)=>{const l=a("DaoTextReading"),o=a("DaoKeywordCards");return h(),u("div",null,[n[0]||(n[0]=e("h1",{id:"论语·雍也",tabindex:"-1"},[i("论语·雍也 "),e("a",{class:"header-anchor",href:"#论语·雍也","aria-label":'Permalink to "论语·雍也"'},"​")],-1)),n[1]||(n[1]=e("h2",{id:"【原典层】原文",tabindex:"-1"},[i("【原典层】原文 "),e("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=e("p",null,"《雍也》三十章，前半评人，后半说理。评人的部分，最动人的两处都与颜回有关：一是哀公问「弟子孰为好学」，孔子答「有颜回者好学，不迁怒，不贰过」，接着说「今也则亡」；二是「一箪食，一瓢饮，在陋巷，人不堪其忧，回也不改其乐」——这是「孔颜之乐」的出处。",-1)),n[3]||(n[3]=e("p",null,[i("说理的部分，几乎句句是名句："),e("strong",null,"文质彬彬、敬鬼神而远之、知者乐水仁者乐山、知之者不如好之者、中庸之为德、己欲立而立人"),i("。这一篇也是《论语》里论「仁」最见方法的一处——子贡问博施济众算不算仁，孔子的回答是：「己欲立而立人，己欲达而达人。能近取譬，可谓仁之方也已。」")],-1)),n[4]||(n[4]=e("p",null,"默认竹简沉浸通读；切「经典阅读」可点生词。",-1)),t(l,{colophon:"雍也第六 · 三十章",tone:"ink",sections:s,glossary:r,"default-mode":"slips","aria-label":"论语·雍也 原文"}),n[5]||(n[5]=e("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[i("【原典层】注音与字词 "),e("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),t(o,{items:[{term:"南面",pinyin:["nán","miàn"],meaning:"面向南而坐，指居君主或长官之位。可使南面：冉雍的器度可以治理一方。"},{term:"大简",pinyin:["tài","jiǎn"],meaning:"同「太简」，过于简略。居简而行简：自己心里就苟简，再以苟简行事。"},{term:"迁怒",pinyin:["qiān","nù"],meaning:"把怒气转移到别人身上。不迁怒：怒于此者不迁于彼。"},{term:"贰过",pinyin:["èr","guò"],meaning:"重复犯同一个错误。贰：重复。"},{term:"釜",pinyin:["fǔ"],meaning:"古量器名，六斗四升为一釜。"},{term:"庾",pinyin:["yǔ"],meaning:"古量器名，二斗四升为一庾（一说十六斗）。"},{term:"五秉",pinyin:["wǔ","bǐng"],meaning:"秉：十六斛（一斛十斗）。五秉数量远超孔子所言，故下文有「周急不继富」之语。"},{term:"周急不继富",pinyin:["zhōu","jí","bù","jì","fù"],meaning:"救济急难，不给富者添财。周：救济；继：增益。"},{term:"骍且角",pinyin:["xīng","qiě","jiǎo"],meaning:"骍：赤色（祭祀用牲以赤为贵）；角：牛角周正，合于祭祀之选。"},{term:"牖",pinyin:["yǒu"],meaning:"窗户。伯牛病重，孔子从窗外握其手，是避嫌，也是情深。"},{term:"箪",pinyin:["dān"],meaning:"盛饭的圆形竹器。一箪食、一瓢饮，形容生活极简朴。"},{term:"画",pinyin:["huà"],meaning:"画地自限、自我设限。今女画：你如今是自己给自己划了界限。"},{term:"伐",pinyin:["fá"],meaning:"自夸。孟之反不伐：孟之反不夸耀自己的功劳。"},{term:"策其马",pinyin:["cè","qí","mǎ"],meaning:"鞭打自己的马。孟之反本殿后掩护，却鞭马装作是马走得慢才落在后面。"},{term:"质胜文则野",pinyin:["zhì","shèng","wén","zé","yě"],meaning:"质朴超过文采，就显得粗野。质：内在质地；文：外在修饰。"},{term:"文质彬彬",pinyin:["wén","zhì","bīn","bīn"],meaning:"文采与质朴配合得恰到好处。彬彬：文质相杂、配合适宜的样子。"},{term:"罔",pinyin:["wǎng"],meaning:"蒙蔽、不直（此处指不正直、虚假地活着）。"},{term:"敬鬼神而远之",pinyin:["jìng","guǐ","shén","ér","yuǎn","zhī"],meaning:"对鬼神存敬而不去逼近、依附。重点在「务民之义」——先尽人事。"},{term:"先难而后获",pinyin:["xiān","nán","ér","hòu","huò"],meaning:"先付出艰难，后取得收获。即先义后利、先劳后得。"},{term:"觚",pinyin:["gū"],meaning:"古代酒器，有棱角。觚不觚：觚已不像觚了——感叹名实不符、制度走样。"},{term:"畔",pinyin:["pàn"],meaning:"同「叛」，背离。弗畔：不会离经叛道。"},{term:"矢",pinyin:["shǐ"],meaning:"同「誓」，发誓。"},{term:"鲜",pinyin:["xiǎn"],meaning:"少。民鲜久矣：人们缺少这种德行已经很久了。"},{term:"己欲立而立人",pinyin:["jǐ","yù","lì","ér","lì","rén"],meaning:"自己要立得住，也让别人立得住；自己要通达，也让别人通达。这是「仁之方」——推己及人的正面表达。"}]}),n[6]||(n[6]=m('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>《雍也》三十章，评人与说理各半。评人的部分，最见分量的是关于颜回的两章：好学（不迁怒、不贰过）与安贫（一箪食一瓢饮而不改其乐）。孔子赞孟之反「不伐」，赞澹台灭明「行不由径」，都是赞同一种东西——<strong>把自己的功劳和姿态都收起来</strong>。</p><p>说理的部分，几乎每章都独立成句。文与质的关系、知与仁的分野、智与仁的不同气质（乐水／乐山，动／静，乐／寿）、学到乐的三层境界，以及最后一章最要紧的：<strong>「己欲立而立人，己欲达而达人。能近取譬，可谓仁之方也已。」</strong>——这是《论语》里对「如何行仁」最直接的方法说明。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它给「好学」定了标准</strong>：不是读得多，而是「不迁怒、不贰过」。<strong>能把情绪收住、把错误改掉，才算学到东西。</strong></li><li><strong>它把「文质」关系讲得最平衡</strong>：「质胜文则野，文胜质则史」——<strong>质朴与修饰，谁都别过头。</strong>「文质彬彬」四个字，成了中国人形容修养的常用语。</li><li><strong>它三层说透了「学」的深浅</strong>：「知之者不如好之者，好之者不如乐之者」——从知道到喜好，再到以此为乐，是三种完全不同的状态。</li><li><strong>它给「智」划了一条底线</strong>：「敬鬼神而远之」——<strong>对不可知者存一份敬，但不把人生的重心交给它。</strong> 先尽人事，这是这一句的真正分量。</li><li><strong>它给出可落地的行仁方法</strong>：「能近取譬」——仁不是抽象的高标，而是<strong>从最近处推想：我要什么，别人也要什么</strong>。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>用「不迁怒、不贰过」做每日的两把标尺</strong>：今天的火，发在了该发的人身上吗？今天犯的错，和昨天是同一个吗？</li><li><strong>检查「文」与「质」的比例</strong>：待人接物，是粗直接近「野」，还是修饰过头近「史」？<strong>找到自己偏的那一边，往中间调。</strong></li><li><strong>把学习目标从「知道」提到「乐」</strong>：一件事能做到「以之为乐」，才算真的进入。</li><li><strong>用「敬而远之」处理不可控的事</strong>：对无常、对运气、对未知，<strong>既不轻慢也不沉溺</strong>——把力气放在能做的事上。</li><li><strong>用「能近取譬」做沟通</strong>：谈判、协作、家庭商量，先问一句「如果我是他，我在意什么」。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>《雍也》这一篇，最动人的是有条件的爱才——它承认了「人是有等差的」。同样好学，孔子只服颜回，因为颜回<strong>不把气撒在别人身上，不犯同一个错</strong>。这不是天赋，是修养。</p><p>它也不回避困难：「力不足者，中道而废，今女画」——孔子明说，<strong>很多人不是做不到，是没打算做到。</strong></p><p>至于「仁」这个字，这一篇给出了最好的注解。子贡问：广施恩惠周济大众，算仁吗？孔子说那已经超过仁、到了圣。仁是什么？<strong>「己欲立而立人，己欲达而达人」</strong>——你自己想站住的地方，也帮别人站住；你自己想走通的路，也让别人走通。</p><p>从最近处推想开去——这就是方法。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「不迁怒，不贰过」——过去一周，我有几次把火发到了不相干的人身上？犯的错里有重复的吗？</li><li>「一箪食，一瓢饮，在陋巷，回也不改其乐」——如果物质条件退一大步，我心里那个「乐」还在吗？</li><li>「今女画」——我有没有用「我不擅长」「我做不到」给自己画过线？那条线是真的吗？</li><li>「能近取譬」——我最近与人合作时，有没有真的从他的位置想过一次？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上篇：<a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-05">论语·公冶长</a>　下篇：<a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-07">论语·述而</a></li><li>参考：《论语》朱熹《四书章句集注·论语集注》；杨伯峻《论语译注》</li></ul>',20))])}}});export{w as __pageData,c as default};
